import json, os, sys, time, urllib.request, urllib.error

BASE = "https://api.assemblyai.com"
KEY = os.environ.get("ASSEMBLYAI_API_KEY")


def call(method, path, body=None, raw=None):
    data = raw if raw is not None else (json.dumps(body).encode() if body is not None else None)
    headers = {"authorization": KEY}
    if raw is None and body is not None:
        headers["content-type"] = "application/json"
    req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=300) as r:
            return json.load(r)
    except urllib.error.HTTPError as e:
        sys.exit(f"AssemblyAI HTTP {e.code}: {e.read().decode(errors='replace')}")


def main():
    if len(sys.argv) != 3:
        sys.exit("usage: transcribe.py <audio.wav> <out.json>")
    if not KEY:
        sys.exit("ASSEMBLYAI_API_KEY not set")
    audio, out = sys.argv[1:]
    with open(audio, "rb") as f:
        upload_url = call("POST", "/v2/upload", raw=f.read())["upload_url"]
    t = call("POST", "/v2/transcript", {
        "audio_url": upload_url,
        "speaker_labels": True,
        "speakers_expected": 2,
        "redact_pii": True,
        "redact_pii_policies": ["us_social_security_number", "phone_number", "person_name"],
        "redact_pii_sub": "hash",
    })
    tid = t["id"]
    while t["status"] not in ("completed", "error"):
        time.sleep(3)
        t = call("GET", f"/v2/transcript/{tid}")
    if t["status"] == "error":
        sys.exit(f"transcription failed ({tid}): {t.get('error')}")
    result = {
        "transcript_id": tid,
        "text": t["text"],
        "utterances": [{"speaker": u["speaker"], "text": u["text"]} for u in (t.get("utterances") or [])],
    }
    with open(out, "w") as f:
        json.dump(result, f, indent=2)


main()
EOF
